-- PASSO 1: Criar tabela
create table if not exists public.unidades (
  id            bigint generated always as identity primary key,
  sigla         text   not null,
  bloco         text,
  unidade       text   not null,
  fracao_ideal  text   not null default '',
  vagas         text   not null default '',
  unique (sigla, bloco, unidade)
);

create index if not exists unidades_sigla_unidade_idx on public.unidades (sigla, unidade);

